def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    for r, row in enumerate(grid):
        end = len(row)
        while end > 0 and row[end - 1] == background:
            end -= 1
        if end == len(row) or end == 0:
            continue

        color = row[end - 1]
        start = end - 1
        while start > 0 and row[start - 1] == color:
            start -= 1

        if end - start >= 5:
            for c in range(end, len(row)):
                out[r][c] = 1

    return out
